//! L3-A wave-62 反例探针：生产默认执行引擎（governed executor / dispatcher）上的
//! `workspace_run_command` 是否真正被 turn 令牌杀死。
//! 只读探针：不改动任何被测源码；仅通过公开 API 观测。

use pony_agent_core::agent::budget::CancellationToken;
use pony_agent_core::agent::dispatcher::DispatchContext;
use pony_agent_core::agent::governed_executor::build_governed_executor_with_sandbox_backend;
use pony_agent_core::agent::sandbox::TestSandboxBackend;
use pony_agent_core::agent::tool_runtime::SandboxBackend;
use pony_agent_core::agent::tools::{ToolCall, ToolExecutionContext, ToolExecutor};
use serde_json::json;
use std::sync::{mpsc, Arc};
use std::time::{Duration, Instant};

#[test]
fn l3a_repro_production_governed_run_ignores_turn_token() {
    let workspace = std::env::temp_dir().join(format!("l3a-repro-{}-{:?}", std::process::id(), std::thread::current().id()));
    std::fs::create_dir_all(&workspace).expect("workspace");
    let marker = workspace.join("l3a-leaked.txt");
    let executor = build_governed_executor_with_sandbox_backend(
        Some(workspace.clone()),
        None,
        Some(Arc::new(TestSandboxBackend::available()) as Arc<dyn SandboxBackend>),
    );
    let token = Arc::new(CancellationToken::new());
    let ctx = ToolExecutionContext {
        workspace_root: Some(workspace.clone()),
        session_id: Some("l3a".to_string()),
        dispatch_context: Some(DispatchContext {
            session_id: Some("l3a".to_string()),
            run_id: Some("run-l3a".to_string()),
            turn_id: Some("turn-l3a".to_string()),
            workspace_root: Some(workspace.display().to_string()),
            turn_cancellation: Some(Arc::clone(&token)),
            ..Default::default()
        }),
        ..Default::default()
    };
    let command = format!("sleep 1.5; echo leaked > '{}'", marker.display());
    let call = ToolCall {
        call_id: Some("call-l3a".to_string()),
        name: "Run".to_string(),
        arguments: json!({ "command": command, "description": "l3a repro", "timeoutMs": 10_000 }),
        plan: None,
    };

    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        let _ = tx.send(executor.execute_with_context(&call, &ctx));
    });

    std::thread::sleep(Duration::from_millis(300));
    let cancelled_at = Instant::now();
    token.cancel();
    let result = rx.recv_timeout(Duration::from_secs(30)).expect("dispatch must return");
    let exit_ms = cancelled_at.elapsed().as_millis() as u64;
    println!("L3A-REPRO status={} exit_ms={} output={}", result.status, exit_ms, result.output);
    std::thread::sleep(Duration::from_millis(1600));
    println!("L3A-REPRO marker_exists={} (true ⇒ 子进程未被取消杀死)", marker.exists());
    assert!(
        exit_ms <= 1000,
        "C3 违约：cancel → 返回耗时 {exit_ms}ms > 1000ms 硬上界（turn 令牌未到达子进程轮询）"
    );
    assert!(!marker.exists(), "C3 违约：取消未真正杀死子进程，命令继续执行并写出副作用");
    let _ = std::fs::remove_dir_all(&workspace);
}
RS
